//! The logistics fixture: a seed-fed project exercising the shapes the
//! sample project cannot — `var()`-controlled enabled/disabled nodes, raw
//! data that lives only in seeds, `ref()` inside hooks, analyses and an
//! `on-run-start` hook, and a vendored local package (macros, a model, a
//! custom generic test).
//!
//! `tests/fixtures/logistics_manifest.json` is generated by REAL dbt from
//! `tests/fixtures/logistics_project/` — regenerate with:
//!
//! ```sh
//! cargo xtask gen-fixture-manifest \
//!     --project tests/fixtures/logistics_project --dbt-version 1.12.6
//! ```
//!
//! Like the sample consistency suite this pins manifest↔source parity, plus
//! the shapes above. Fixture-specific documented differences (beyond the
//! shared ones in `common::consistency`):
//! - Compiled-only lint rules (`unused_cte`, `order_by_without_limit`) fire
//!   only in manifest mode: the `shipkit` macro's expansion exists solely
//!   in `compiled_code`, while source mode's raw text is a bare unresolved
//!   `{{ shipkit.audited_select(...) }}` call.
//! - The singular `.sql` test registers on `ops_run_log` in the manifest;
//!   source mode never synthesizes singular tests, so its `tests:N` badge
//!   differs — the lineage-render comparison skips the handful of nodes
//!   whose subgraph carries that badge.

mod common;
use common::consistency as cmp;
use common::{LOGISTICS_MANIFEST as MANIFEST, LOGISTICS_PROJECT as PROJECT};
use std::collections::{BTreeMap, BTreeSet};

use dbtl::{
    build_model_list, layout, load_dag, run_rules, Dag, LintConfig, LintInput, PackageScope,
    SortMode, SqlDialect, SqlParseResolver,
};

/// (manifest-mode Dag, source-mode Dag) of the logistics project, manifest
/// side already scoped to the root project.
fn dags() -> (Dag, Dag) {
    cmp::dags(
        MANIFEST,
        PROJECT,
        "cargo xtask gen-fixture-manifest --project tests/fixtures/logistics_project",
    )
}

#[test]
fn node_sets_and_infos_are_identical() {
    let (m, s) = dags();
    cmp::assert_node_infos_identical(&m, &s, cmp::NO_DROPPED_EDGES);
}

#[test]
fn full_lineage_closures_are_identical() {
    let (m, s) = dags();
    cmp::assert_closures_identical(&m, &s, cmp::NO_DROPPED_EDGES);
}

#[test]
fn details_are_identical_modulo_profile_data() {
    let (m, s) = dags();
    cmp::assert_details_identical(&m, &s);
}

#[test]
fn tests_are_identical_as_kind_column_multisets() {
    // Covers generic schema tests (unique/not_null/relationships), the seed
    // column tests, and the package's custom `no_negative_amounts` generic —
    // all registered identically in both modes; the singular test rides the
    // shared manifest-side exclusion.
    let (m, s) = dags();
    cmp::assert_tests_identical(&m, &s);
}

#[test]
fn project_name_is_identical() {
    let (m, s) = dags();
    assert_eq!(m.project_name(), Some("logistics"), "manifest mode");
    assert_eq!(s.project_name(), Some("logistics"), "source mode");
}

#[test]
fn var_disabled_nodes_are_absent_in_both_modes() {
    // Every `var()`-driven disable channel parks the node under dbt's
    // `disabled` (never `nodes`), so both modes must drop them all:
    //   experimental/*       models: tree `+enabled: var('enable_experimental')` (unset → false)
    //   fct_lane_pairs       in-file `config(enabled=var('lane_pairs_enabled'))` — the
    //                        project-scoped vars.yml entry (false) shadows the top-level (true)
    //   fct_returns          in-file `config(enabled=var('track_returns', false))` (unset → default)
    //   assert_events_in_order  singular test, in-file `config(enabled=var('strict_event_check', false))`
    //   deep_audit_probe     analyses: tree `+enabled: var('probe_enabled', false)`
    let (m, s) = dags();
    for uid in [
        "model.logistics.exp_demand_forecast",
        "model.logistics.exp_empty_miles",
        "model.logistics.fct_lane_pairs",
        "model.logistics.fct_returns",
        "test.logistics.assert_events_in_order",
        "analysis.logistics.deep_audit_probe",
    ] {
        assert!(!m.contains(uid), "manifest mode keeps {uid}");
        assert!(!s.contains(uid), "source mode keeps {uid}");
    }
    // …and the nodes the same vars turn ON must be present in both modes:
    //   pilot/*              models: tree `+enabled: var('enable_pilot')` → vars.yml true
    //   fct_service_alerts   in-file `config(enabled=var('alerts_enabled'))` → vars.yml true
    for uid in [
        "model.logistics.pilot_dock_queue",
        "model.logistics.pilot_lane_estimates",
        "model.logistics.fct_service_alerts",
    ] {
        assert!(m.contains(uid), "manifest mode drops {uid}");
        assert!(s.contains(uid), "source mode drops {uid}");
    }
}

#[test]
fn hook_ref_is_an_edge_in_both_modes() {
    // `ref('ops_run_log')` inside `fct_shipments`' pre/post-hook SQL is a real
    // `depends_on` edge in the manifest — and the source loader's `ref()`
    // scan covers `config()` strings too, so source mode builds the same
    // edge. Pinned directly so a future change to either side is loud.
    let (m, s) = dags();
    let child = "model.logistics.fct_shipments";
    let parent = "model.logistics.ops_run_log";
    for (mode, dag) in [("manifest", &m), ("source", &s)] {
        assert!(
            dag.direct_parents(child).iter().any(|p| p == parent),
            "{mode} mode lost the hook-ref edge"
        );
    }
}

#[test]
fn model_list_groups_are_identical() {
    // Left-pane grouping is edge-independent, so it compares exactly.
    let (m, s) = dags();
    let groups = |l: &dbtl::ModelList| -> Vec<(String, Vec<String>)> {
        l.groups
            .iter()
            .map(|g| {
                (
                    g.layer.clone(),
                    g.models.iter().map(|n| n.name.clone()).collect(),
                )
            })
            .collect()
    };
    assert_eq!(
        groups(&build_model_list(&m, SortMode::Layer)),
        groups(&build_model_list(&s, SortMode::Layer)),
        "left-pane grouping diverges"
    );
}

#[test]
fn lineage_renders_identical_outside_the_singular_badge_cone() {
    // The only render-visible divergence is the `tests:N` badge on
    // `ops_run_log` (the manifest's singular test registers there; source
    // mode never synthesizes it). A node's badge shows in its own lineage
    // and every ancestor/descendant's, so exactly the nodes whose subgraph
    // contains it are skipped — pinned to the two expected uids.
    let (m, s) = dags();
    let mut skip = BTreeSet::new();
    for uid in cmp::node_map(&m).keys() {
        if m.tests(uid).iter().any(|t| t.kind == "singular") {
            skip.insert(uid.clone());
            skip.extend(m.upstream(uid));
            skip.extend(m.downstream(uid));
        }
    }
    assert_eq!(
        skip,
        BTreeSet::from([
            "model.logistics.fct_shipments".to_string(),
            "model.logistics.ops_run_log".to_string(),
        ]),
        "the singular-test badge cone grew — re-check the fixture"
    );
    for uid in cmp::node_map(&m).keys() {
        if skip.contains(uid) {
            continue;
        }
        assert_eq!(
            layout(&m.subgraph(uid)).grid.to_text(),
            layout(&s.subgraph(uid)).grid.to_text(),
            "lineage render diverges for {uid}"
        );
    }
}

/// Per-rule finding counts for a dag, with the SQL resolver CLI lint uses.
fn rule_counts(dag: &Dag) -> BTreeMap<String, usize> {
    let cfg = LintConfig::default();
    let sql = SqlParseResolver::new(None, SqlDialect::from_dag(dag));
    let outcome = run_rules(LintInput::new(dag, &cfg).with_sql(Some(&sql)));
    let mut counts = BTreeMap::new();
    for f in &outcome.findings {
        *counts.entry(f.rule.name().to_string()).or_default() += 1;
    }
    counts
}

#[test]
fn lint_rule_counts_match_except_compiled_only_rules() {
    // Every rule must produce the same count in both modes EXCEPT the two
    // SQL rules that legitimately see only manifest-mode compiled SQL (the
    // shipkit macro expansion): `unused_cte` and `order_by_without_limit`.
    let (m, s) = dags();
    let mc = rule_counts(&m);
    let sc = rule_counts(&s);
    for rule in mc.keys().chain(sc.keys()).collect::<BTreeSet<_>>() {
        let m_count = mc.get(rule).copied().unwrap_or(0);
        let s_count = sc.get(rule).copied().unwrap_or(0);
        match rule.as_str() {
            "unused_cte" | "order_by_without_limit" => continue, // pinned below
            _ => assert_eq!(m_count, s_count, "lint:{rule} counts diverge between modes"),
        }
    }
    assert_eq!(mc.get("unused_cte"), Some(&1), "manifest mode");
    assert_eq!(sc.get("unused_cte"), None, "source mode");
    assert_eq!(mc.get("order_by_without_limit"), Some(&1), "manifest mode");
    assert_eq!(sc.get("order_by_without_limit"), None, "source mode");
}

#[test]
fn compiled_only_lints_point_at_the_macro_call_site() {
    // Both compiled-only findings land on fct_audited_shipments — the model
    // whose entire body is the shipkit macro call — proving they come from
    // `compiled_code`, not the raw macro call.
    let (m, _s) = dags();
    let cfg = LintConfig::default();
    let sql = SqlParseResolver::new(None, SqlDialect::from_dag(&m));
    let mf = run_rules(LintInput::new(&m, &cfg).with_sql(Some(&sql))).findings;
    let audited: BTreeSet<&str> = mf
        .iter()
        .filter(|f| f.node_uid == "model.logistics.fct_audited_shipments")
        .map(|f| f.rule.name())
        .collect();
    for rule in ["unused_cte", "order_by_without_limit"] {
        assert!(
            audited.contains(rule),
            "{rule} did not fire on fct_audited_shipments in manifest mode"
        );
    }
}

#[test]
fn package_nodes_are_hidden_by_default() {
    // Under the default root-project scope the vendored package contributes
    // macros and tests but no nodes: `model.shipkit.shipkit_audit_trail`
    // must be absent — matching source mode, which never sees packages.
    let (m, _s) = dags();
    assert!(
        !m.contains("model.shipkit.shipkit_audit_trail"),
        "package node leaked into root scope"
    );
}

#[test]
fn package_nodes_appear_with_include_packages() {
    // `PackageScope::All` (the `--include-packages` flag) widens the graph to
    // the installed package: the shipkit model appears with its edges into
    // the root project's staging models.
    let full = load_dag(MANIFEST).expect("fixture manifest loads");
    let (all, _warnings) = PackageScope::All.apply_with_warnings(full);
    assert!(
        all.contains("model.shipkit.shipkit_audit_trail"),
        "--include-packages dropped the package model"
    );
    assert_eq!(
        all.direct_parents("model.shipkit.shipkit_audit_trail")
            .to_vec(),
        vec![
            "model.logistics.stg_shipment_events".to_string(),
            "model.logistics.stg_shipments".to_string(),
        ],
        "package model parents diverge"
    );
}

#[test]
fn package_nodes_provide_context_but_are_never_flagged() {
    // Under All scope the package model joins the graph for dependency
    // context, but lint in-scope stays root-only: no finding may point at a
    // shipkit node — and widening scope must not shift root findings.
    let full = load_dag(MANIFEST).expect("fixture manifest loads");
    let (all, _warnings) = PackageScope::All.apply_with_warnings(full);
    let all_counts = rule_counts(&all);
    let cfg = LintConfig::default();
    let sql = SqlParseResolver::new(None, SqlDialect::from_dag(&all));
    let outcome = run_rules(LintInput::new(&all, &cfg).with_sql(Some(&sql)));
    for f in &outcome.findings {
        assert!(
            !f.node_uid.starts_with("model.shipkit."),
            "package node {} was flagged by {}",
            f.node_uid,
            f.rule.name()
        );
    }
    let (m, _s) = dags();
    assert_eq!(
        all_counts,
        rule_counts(&m),
        "package scope shifted findings"
    );
}

#[test]
fn singular_test_registers_on_its_dependency_in_manifest() {
    // The shared exclusion, pinned directly: the manifest carries
    // `assert_run_log_model_name` on the node its SQL refs; source mode has
    // no singular tests at all.
    let (m, s) = dags();
    let uid = "model.logistics.ops_run_log";
    let kinds: Vec<&str> = m.tests(uid).iter().map(|t| t.kind.as_str()).collect();
    assert!(
        kinds.contains(&"singular"),
        "manifest mode lost the singular test on {uid}"
    );
    assert!(
        !s.tests(uid).iter().any(|t| t.kind == "singular"),
        "source mode synthesized a singular test on {uid}"
    );
}

#[test]
fn analyses_and_disabled_tests_never_enter_the_graph() {
    // analyses are recorded in the manifest (`analysis.*` nodes) but are not
    // lineage resources — same for the var-disabled singular test: neither
    // side exposes them.
    let (m, s) = dags();
    for uid in [
        "analysis.logistics.weekly_lane_review",
        "test.logistics.assert_events_in_order",
    ] {
        assert!(!m.contains(uid), "manifest mode keeps {uid}");
        assert!(!s.contains(uid), "source mode keeps {uid}");
    }
}
